"""fixtures.py: stand-ins for Lab 3 (you do not edit this file).

A templated slice of the benchmark ("fee for a deck of C square metres") so that every question has a
*fresh variant*: the same problem with new numbers. A fake model "memorises" the originals it was shown
(it recites their keys) and otherwise answers with real ability. It is a RuleModel from llm.py, the
same stand-in the other labs use, so it is deterministic and offline.

    make_problems(n)            -> (originals, variants): two lists of (question, answer) pairs, index i of
                                   each list is the same template with different numbers
    make_model(memorised)       -> a model that recites the key for each (question, answer) in `memorised`
    correct_flags(model, probs) -> [1 or 0 per problem]: did the model's reply equal the key?
"""
import random
import re
import zlib

from llm import RuleModel, text_of

TEMPLATE = ("A residential deck permit has a base fee of {a} dollars plus {b} dollars for each square metre "
            "of deck. What is the fee for a deck of {c} square metres?")
GENERIC = r"base fee of (\d+) dollars plus (\d+) dollars for each square metre of deck\. What is the fee for a deck of (\d+) square"
ABILITY = 0.70


def _one(rng):
    a, b, c = rng.randint(40, 200), rng.randint(2, 9), rng.randint(8, 29)
    return TEMPLATE.format(a=a, b=b, c=c), str(a + b * c)


def make_problems(n=150, seed=11):
    """n templated problems and, for each, a fresh variant with new numbers. Returns (originals, variants)."""
    rng = random.Random(seed)
    originals, variants = [], []
    for _ in range(n):
        originals.append(_one(rng))
        variants.append(_one(rng))
    return originals, variants


def _skill(ability):
    """Right on `ability` of questions, decided by a hash of the question so that it is deterministic."""
    def reply(m):
        a, b, c = map(int, m.groups())
        right = a + b * c
        ok = zlib.crc32(m.group(0).encode()) % 100 < ability * 100
        return str(right if ok else right + 10)
    return reply


def make_model(memorised, ability=ABILITY):
    """A model that recites the key of every memorised (question, answer) and otherwise has real ability."""
    rules = [(re.escape(q), ans) for q, ans in memorised]
    rules.append((GENERIC, _skill(ability)))
    return RuleModel(rules)


def correct_flags(model, problems):
    """1 if the model's reply to the question equals the key, else 0, for each (question, answer)."""
    return [int(text_of(model.complete([{"role": "user", "content": q}])).strip() == ans) for q, ans in problems]
